<template>
  <component :is="embedded ? 'main' : ElDrawer" :model-value="embedded ? undefined : modelValue" title="写作实验室" size="min(1180px,96vw)" :append-to-body="embedded ? undefined : true" :class="['writing-workspace',{embedded}]" @update:model-value="emit('update:modelValue',$event)" @open="loadAll">
    <div class="writing-boundary"><b>写作研究边界</b><span>内容只取自你明确选择的库内文献或知识对象；Writing DNA 只约束写法，不复制原文观点，也不冒充原作者；去 AI 味只做可审阅的表达约束。</span></div>
    <el-tabs v-model="mode" class="writing-tabs">
      <el-tab-pane label="写作 DNA" name="dna">
        <div class="dna-layout">
          <aside class="dna-sidebar">
            <header><b>DNA 项目</b><el-button size="small" plain @click="creating=!creating">{{ creating?'收起':'新建' }}</el-button></header>
            <div v-if="creating" class="profile-form">
              <el-input v-model="profileForm.name" placeholder="项目名称，例如：我的评论写作" />
              <el-input v-model="profileForm.target_author" placeholder="作者或账号（可选）" />
              <el-select v-model="profileForm.book_ids" multiple collapse-tags filterable remote :remote-method="searchBooks" :loading="booksLoading" placeholder="搜索并选择至少20篇完整文章">
                <el-option v-for="book in bookOptions" :key="book.id" :label="book.title" :value="book.id" />
              </el-select>
              <span :class="['corpus-count',{ready:profileForm.book_ids.length>=20}]">{{ profileForm.book_ids.length }}/20 篇最低语料</span>
              <el-checkbox v-model="profileForm.rights_acknowledged">我确认有权处理所选文章</el-checkbox>
              <el-button type="primary" :disabled="!canDistill" :loading="submitting" @click="createProfile">开始蒸馏</el-button>
            </div>
            <button v-for="profile in profiles" :key="profile.id" :class="['profile-row',{active:selectedProfileId===profile.id}]" @click="openProfile(profile.id)">
              <span><b>{{ profile.name }}</b><small>{{ profile.corpus_count }}篇 · v{{ profile.current_version }}</small></span>
              <el-tag size="small" :type="statusType(profile.status)">{{ statusText(profile.status) }}</el-tag>
            </button>
            <StudyEmptyState v-if="!profiles.length&&!creating" compact title="尚无 Writing DNA" description="从至少20篇完整文章建立第一版。" />
          </aside>
          <main class="dna-main">
            <StudyEmptyState v-if="!profileDetail" title="选择或新建 DNA 项目" description="系统会分别保存语言、逻辑结构、文章结构、选题与认知、视觉和整合 DNA，并保留每次完善版本。" />
            <template v-else>
              <div class="profile-head"><div><span>Writing DNA · v{{ profileDetail.current_version }}</span><h3>{{ profileDetail.name }}</h3><p>{{ profileDetail.corpus_count }} 篇完整文章 · {{ profileDetail.target_author||'未指定作者' }}</p></div><div class="version-tools"><el-select v-if="profileDetail.revisions?.length" v-model="selectedRevisionId" size="small" aria-label="查看历史版本"><el-option v-for="revision in profileDetail.revisions" :key="revision.id" :label="`查看 v${revision.version}`" :value="revision.id" /></el-select><el-select v-if="profileDetail.revisions?.length>1" v-model="compareRevisionId" clearable size="small" placeholder="比较版本" aria-label="比较历史版本"><el-option v-for="revision in profileDetail.revisions.filter(item=>item.id!==selectedRevisionId)" :key="revision.id" :label="`比较 v${revision.version}`" :value="revision.id" /></el-select><el-tag :type="statusType(profileDetail.status)">{{ statusText(profileDetail.status) }}</el-tag><el-button text size="small" type="danger" :loading="submitting" @click="removeProfile">删除项目</el-button></div></div>
              <el-alert v-if="profileDetail.error_msg" type="error" :title="profileDetail.error_msg" show-icon />
              <el-alert v-if="profileDetail.missing_book_ids?.length" type="warning" :closable="false" show-icon :title="`语料中 ${profileDetail.missing_book_ids.length} 篇文章已从书库删除（见下方清单标记）；下次“生成下一版本”时会自动移除，若不足 20 篇请先补充语料。`" />
              <template v-if="activeRevision">
                <div class="quality-strip"><span><b>{{ activeRevision.quality?.article_count||profileDetail.corpus_count }}</b>文章</span><span><b>{{ activeRevision.quality?.structure_type_count||'—' }}</b>结构类型</span><span><b>{{ activeRevision.quality?.logic_pattern_count||'—' }}</b>逻辑模式</span><span><b>{{ activeRevision.quality?.cognitive_claim_count||'—' }}</b>认知命题</span><span><b>{{ activeRevision.quality?.visual_sample_count||0 }}</b>视觉样本</span></div>
                <div v-if="activeRevision.quality?.limitations?.length" class="quality-limit"><b>本版限制</b><span>{{ activeRevision.quality.limitations.join('；') }}</span></div>
                <section v-if="comparisonRevision" class="revision-compare"><header><b>v{{ activeRevision.version }} 与 v{{ comparisonRevision.version }}</b><el-button text size="small" @click="compareRevisionId=null">结束比较</el-button></header><div><span>语料 {{ activeRevision.quality?.article_count||0 }} / {{ comparisonRevision.quality?.article_count||0 }}</span><span>结构类型 {{ activeRevision.quality?.structure_type_count||'—' }} / {{ comparisonRevision.quality?.structure_type_count||'—' }}</span><span>认知命题 {{ activeRevision.quality?.cognitive_claim_count||'—' }} / {{ comparisonRevision.quality?.cognitive_claim_count||'—' }}</span></div><el-collapse><el-collapse-item title="并排核对整合 DNA" name="compare"><div class="compare-text"><article v-html="renderMarkdown(activeRevision.writing_dna)"/><article v-html="renderMarkdown(comparisonRevision.writing_dna)"/></div></el-collapse-item></el-collapse></section>
                <details class="corpus-audit"><summary>核对语料清单 · {{ profileDetail.corpus_manifest?.length||0 }} 篇</summary><div v-if="removeBookIds.length" class="corpus-pending">下一版将排除 {{ removeBookIds.length }} 篇；至少仍需保留 20 篇。</div><div class="corpus-rows"><div v-for="item in profileDetail.corpus_manifest" :key="item.book_id" :class="{removed:removeBookIds.includes(item.book_id)}"><span><b>{{ item.title }}</b><small>{{ item.file_type?.toUpperCase() }} · {{ item.chars?.toLocaleString() }} 字符</small></span><div><el-tag v-if="profileDetail.missing_book_ids?.includes(item.book_id)" size="small" type="danger" effect="plain">已删除</el-tag><el-tag v-if="item.image_count" size="small" effect="plain">图像 {{ item.image_count }}</el-tag><el-button text size="small" @click="toggleCorpusRemoval(item.book_id)">{{ removeBookIds.includes(item.book_id)?'恢复':'下一版排除' }}</el-button></div></div></div></details>
                <el-collapse accordion class="artifact-list">
                  <el-collapse-item title="Writing-DNA（整合）" name="all"><article v-html="renderMarkdown(activeRevision.writing_dna)" /></el-collapse-item>
                  <el-collapse-item title="语言 DNA" name="language"><article v-html="renderMarkdown(activeRevision.language_dna)" /></el-collapse-item>
                  <el-collapse-item title="文章结构模板" name="structure"><article v-html="renderMarkdown(activeRevision.structure_patterns)" /></el-collapse-item>
                  <el-collapse-item v-if="activeRevision.logic_dna" title="逻辑结构 DNA" name="logic"><article v-html="renderMarkdown(activeRevision.logic_dna)" /></el-collapse-item>
                  <el-collapse-item title="写作视角与认知框架" name="cognitive"><article v-html="renderMarkdown(activeRevision.cognitive_framework)" /></el-collapse-item>
                  <el-collapse-item title="视觉风格指南" name="visual"><article v-html="renderMarkdown(activeRevision.visual_style_guide)" /></el-collapse-item>
                </el-collapse>
              </template>
              <section class="refine-panel"><header><b>持续完善</b><small>补充、排除文章或写下修正意见，会生成新版本并保留旧版。</small></header><el-select v-model="refineBooks" multiple collapse-tags filterable remote :remote-method="searchBooks" :loading="booksLoading" placeholder="补充语料（可选）"><el-option v-for="book in bookOptions" :key="book.id" :label="book.title" :value="book.id" /></el-select><el-input v-model="refineFeedback" type="textarea" :rows="2" placeholder="例如：减少对早期文章的权重；视觉分析补充截图型证据。" /><el-button :disabled="!refineBooks.length&&!removeBookIds.length&&!refineFeedback.trim()" :loading="submitting" @click="refineProfile">生成下一版本</el-button></section>
            </template>
          </main>
        </div>
      </el-tab-pane>
      <el-tab-pane label="写作生成" name="generate">
        <div class="generate-layout">
          <section class="generate-config">
            <header><div><span>{{ genMode==='imitate' ? 'IMITATION FROM KNOWLEDGE' : 'SELECTED CORPUS REVIEW' }}</span><h3>{{ genMode==='imitate' ? '按 Writing DNA 写一篇新文章' : '从已选文献建立证据对话' }}</h3></div><el-tag effect="plain">{{ genMode==='imitate' ? '取材知识对象' : '封闭语料' }}</el-tag></header>
            <el-radio-group v-model="genMode" class="gen-mode"><el-radio-button value="imitate">独立仿写</el-radio-button><el-radio-button value="review">多文献综述</el-radio-button></el-radio-group>
            <template v-if="genMode==='imitate'">
              <label class="review-field"><span>Writing DNA <small>必选：校准语言、结构、逻辑与认知</small></span><el-select v-model="genProfileId" clearable placeholder="选择一个已就绪的 DNA 项目" @change="loadGenProfile"><el-option v-for="profile in readyProfiles" :key="profile.id" :label="`${profile.name} · v${profile.current_version}`" :value="profile.id" /></el-select></label>
              <label class="review-field"><span>取材知识对象 <small>必选：笔记 / 证据卡 / 批判性审查报告</small></span><el-select v-model="imitateForm.knowledge_keys" multiple filterable collapse-tags :loading="knowledgeLoading" placeholder="至少选择一个取材对象"><el-option v-for="item in knowledgeOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select></label>
              <div class="review-fields three"><label class="review-field"><span>题目或议题</span><el-input v-model="imitateForm.topic" placeholder="新文章题目或议题" /></label><label class="review-field"><span>体裁</span><el-select v-model="imitateForm.genre"><el-option label="深度文章" value="深度文章"/><el-option label="评论" value="评论"/><el-option label="短评" value="短评"/><el-option label="综述" value="综述"/></el-select></label><label class="review-field"><span>目标字数</span><el-input-number v-model="imitateForm.length" :min="300" :max="12000" :step="100" controls-position="right" style="min-width:150px" /></label></div>
              <label class="review-field"><span>补充要求 <small>本次立场、素材边界与发布场景</small></span><el-input v-model="imitateForm.brief" type="textarea" :rows="2" placeholder="例如：站在政策执行者视角，只使用已选证据卡。" /></label>
              <el-alert type="info" :closable="false" title="事实与观点只能来自所选取材对象；Writing DNA 只校准写法，不复制原文观点。" />
              <el-button type="primary" size="large" :loading="generating" :disabled="!imitateForm.topic.trim() || !imitateForm.knowledge_keys.length || !genProfileId" @click="runImitation">生成独立新作</el-button>
            </template>
            <template v-else>
              <p class="review-intro">至少选择 2 篇已解析文献。系统公平抽取每篇文献的首、中、尾与议题相关片段，并保留页码/分块锚点。需要带来源主张审计的研究报告（含假设与竞争性解释），请用「研读与沉淀 → 研究报告」。</p>
              <el-alert type="info" :closable="false" title="这是个人知识库内的叙事综述、范围梳理或证据图谱，不是系统综述，也不宣称 PRISMA 合规。" />
              <label class="review-field"><span>已选文献 <small>{{ reviewForm.book_ids.length }} 篇</small></span><el-select v-model="reviewForm.book_ids" multiple filterable remote collapse-tags collapse-tags-tooltip :remote-method="searchBooks" :loading="booksLoading" placeholder="搜索并至少选择 2 篇已解析文献"><el-option v-for="book in bookOptions" :key="book.id" :label="book.title" :value="book.id" /></el-select></label>
              <div class="review-fields two"><label class="review-field"><span>综述题目</span><el-input v-model="reviewForm.title" placeholder="例如：地方治理研究中的参与机制" /></label><label class="review-field"><span>核心问题</span><el-input v-model="reviewForm.question" placeholder="这些文献在哪些条件下形成共识或冲突？" /></label></div>
              <div class="review-fields three"><label class="review-field"><span>综合路径</span><el-select v-model="reviewForm.review_type"><el-option label="主题型叙事综述" value="narrative"/><el-option label="范围梳理" value="scoping"/><el-option label="证据图谱" value="evidence_map"/></el-select></label><label class="review-field"><span>学科审查镜头</span><el-select v-model="reviewForm.discipline"><el-option label="自动 / 跨学科" value="auto"/><el-option label="社会科学" value="social_science"/><el-option label="人文与文学" value="humanities"/><el-option label="自然科学与生物医学" value="natural_biomedical"/></el-select></label><label class="review-field"><span>目标长度 <small>1,200–20,000 字</small></span><el-input v-model.number="reviewForm.length" type="number" min="1200" max="20000" step="100" inputmode="numeric" /></label></div>
              <label class="review-field"><span>Writing DNA <small>可选：只校准表达，不参与事实判断</small></span><el-select v-model="reviewForm.profile_id" clearable placeholder="可选：选择已就绪 DNA"><el-option v-for="profile in readyProfiles" :key="profile.id" :label="`${profile.name} · v${profile.current_version}`" :value="profile.id" /></el-select></label>
              <el-button type="primary" size="large" :loading="reviewingLiterature" :disabled="!canGenerateReview" @click="runLiteratureReview">生成多文献综述</el-button>
            </template>
            <p class="provider-note">两种模式都始终执行四条 AI 味硬性禁令：禁翻案式铺垫、禁例证复用、禁“不是……而是……”、禁定语后置。所选材料才会进入提示词。</p>
          </section>
          <section class="generate-result">
            <StudyEmptyState v-if="!generatedOutput" title="等待生成结果" description="结果会同时保存在「写作输出」，可继续去 AI 味、编辑或下载 Word。" />
            <template v-else>
              <header><div><span v-if="generatedOutput.kind==='literature_review'">证据锚点 {{ generatedOutput.audit?.citation_count||0 }} · 覆盖 {{ generatedOutput.audit?.cited_book_ids?.length||0 }}/{{ generatedOutput.audit?.book_ids?.length||0 }} 篇</span><span v-else>IMITATION DRAFT</span><h3>{{ generatedOutput.title }}</h3></div><div><el-button plain @click="sendToTone(generatedOutput)">去 AI 味</el-button><el-button text @click="openInOutputs(generatedOutput.id)">在写作输出中查看</el-button><a :href="writingOutputDownloadUrl(generatedOutput.id)">下载 Word</a></div></header>
              <el-alert v-if="freshnessWarning" :type="freshnessType" :closable="false" :title="generatedOutput.source_freshness.message"/>
              <el-alert v-if="generatedOutput.kind==='literature_review' && generatedOutput.audit?.unreferenced_book_ids?.length" type="warning" :closable="false" :title="`有 ${generatedOutput.audit.unreferenced_book_ids.length} 篇已选文献未出现在正文锚点中，请人工核对。`" />
              <el-alert v-if="generatedOutput.kind==='literature_review' && generatedOutput.audit?.citation_warning" type="warning" :closable="false" :title="generatedOutput.audit.citation_warning" />
              <el-alert v-if="currentViolations" type="warning" :closable="false" :title="`AI 味硬性禁令检测：疑似违规 ${currentViolations.total} 处（${currentViolations.detail}）`" :description="currentViolations.samples" />
              <div class="review-audit"><span v-if="generatedOutput.kind==='literature_review'">限定：已选文献</span><span v-if="generatedOutput.kind==='literature_review'">{{ generatedOutput.audit?.discipline }} · {{ generatedOutput.audit?.review_type }}</span><span v-if="generatedOutput.audit?.dna_version">Writing DNA v{{ generatedOutput.audit.dna_version }}</span><span v-else>未使用 Writing DNA</span></div>
              <article class="markdown-body" v-html="renderMarkdown(generatedOutput.output_text)" />
            </template>
          </section>
        </div>
      </el-tab-pane>
      <el-tab-pane label="去 AI 味" name="clean">
        <div class="clean-layout">
          <section class="clean-input">
            <header><b>白名单式最小改写</b><small>只处理13类可定位痕迹；结构、事实、数字、引语、链接和限定词保持不变。</small></header>
            <label class="review-field"><span>Writing DNA <small>可选：以语言、逻辑与整合层判断机械痕迹，不参与事实判断</small></span><el-select v-model="cleanProfileId" clearable placeholder="不选则按原体裁判断"><el-option v-for="profile in readyProfiles" :key="profile.id" :label="`${profile.name} · v${profile.current_version}`" :value="profile.id" /></el-select></label>
            <el-input v-model="cleanText" type="textarea" :rows="16" maxlength="120000" show-word-limit placeholder="粘贴需要处理的文本" />
            <div class="clean-actions"><el-button type="primary" :loading="cleaning" :disabled="!cleanText.trim()" @click="runTextClean">处理文本</el-button><el-upload :show-file-list="false" :auto-upload="false" accept=".docx" :on-change="runDocxClean"><el-button :loading="cleaning">导入 Word 并输出 Word</el-button></el-upload></div>
          </section>
          <section class="clean-output">
            <header><b>输出与审计</b><a v-if="currentOutput?.download_ready" :href="writingOutputDownloadUrl(currentOutput.id)">下载 Word</a></header>
            <StudyEmptyState v-if="!currentOutput||currentOutput.kind!=='ai_tone'" compact title="尚无处理结果" description="未命中白名单的文字会原样保留。" />
            <template v-else><div class="audit-strip"><span>候选 {{ outputChanges.length }} 处</span><span>已选择 {{ acceptedIndexes.length }} 处</span><span>拒绝 {{ currentOutput.audit?.rejected?.length||0 }} 处越界改写</span><span v-if="currentRemaining">残留违规 {{ currentRemaining.total }} 处</span></div><el-alert v-if="currentRemaining" type="warning" :closable="false" :title="`处理后仍残留 AI 味违规 ${currentRemaining.total} 处（${currentRemaining.detail}），多为需要整段改写或删减的问题，请人工处理。`" :description="currentRemaining.samples" /><div v-if="outputChanges.length" class="change-review"><header><b>逐条决定是否采用</b><el-checkbox :model-value="acceptedIndexes.length===outputChanges.length" @change="toggleAllChanges">全选</el-checkbox></header><label v-for="(change,index) in outputChanges" :key="`${change.id}-${index}`"><el-checkbox v-model="acceptedIndexes" :value="index"/><span><del>{{ change.old }}</del><ins>{{ change.new||'（删除）' }}</ins><small>规则 {{ change.rule_ids?.join('、') }}</small></span></label><el-button type="primary" plain :loading="reviewing" @click="applyReviewedChanges">按选择重新生成 Word</el-button></div><el-input v-model="currentOutput.output_text" type="textarea" :rows="12" readonly /></template>
          </section>
        </div>
      </el-tab-pane>
      <el-tab-pane label="写作输出" name="outputs">
        <div class="output-layout">
          <aside class="output-history"><header><b>全部写作输出</b><div><el-select v-model="outputFilter" size="small" placeholder="全部类型" @change="loadOutputs(1)"><el-option label="全部类型" value=""/><el-option label="独立新作" value="imitation"/><el-option label="多文献综述" value="literature_review"/><el-option label="去 AI 味" value="ai_tone"/></el-select><el-button text size="small" @click="loadOutputs()">刷新</el-button></div></header><p class="output-note">汇总独立新作、多文献综述与去 AI 味结果；打开后可编辑正文、下载 Word 或继续去 AI 味。</p><button v-for="item in outputs" :key="item.id" :class="{active:currentOutput?.id===item.id}" @click="openOutput(item.id)"><span><b>{{ item.title }}</b><small>{{ outputKindText(item.kind) }} · {{ item.output_length?.toLocaleString() }} 字</small></span><time>{{ formatDate(item.created_at) }}</time></button><StudyEmptyState v-if="!outputs.length" compact title="尚无写作输出" description="生成或处理稿件后会保存在这里。"/><el-pagination v-if="outputTotal>20" small layout="prev, pager, next" :total="outputTotal" :page-size="20" @current-change="loadOutputs"/></aside>
          <main class="output-detail"><StudyEmptyState v-if="!currentOutput" title="选择一条输出" description="正文按需加载，不在列表中返回完整内容。"/><template v-else><header><div><span>{{ outputKindText(currentOutput.kind) }}</span><h3>{{ currentOutput.title }}</h3></div><div><el-button v-if="currentOutput.kind!=='ai_tone'&&!editingOutput" plain @click="beginEditOutput">编辑</el-button><el-button v-if="currentOutput.kind==='literature_review'" plain @click="sendReviewToTone">送去 AI 味审阅</el-button><el-button v-if="currentOutput.kind==='ai_tone'" plain @click="mode='clean'">逐条审阅</el-button><a v-if="currentOutput.download_ready" :href="writingOutputDownloadUrl(currentOutput.id)">下载 Word</a></div></header><el-alert v-if="freshnessWarning" :type="freshnessType" :closable="false" :title="currentOutput.source_freshness.message"/><div v-if="currentOutput.kind==='ai_tone'&&outputChanges.length" class="history-audit">{{ outputChanges.length }} 项候选修改 · 已采用 {{ currentOutput.audit?.accepted_indexes?.length ?? outputChanges.length }} 项 · 规则 {{ (currentOutput.audit?.rules||[]).join('、') }}</div><template v-if="editingOutput"><el-input v-model="draftTitle"/><el-input v-model="draftText" type="textarea" :rows="22" maxlength="200000" show-word-limit/><div class="edit-actions"><el-button @click="cancelEditOutput">取消</el-button><el-button type="primary" :loading="savingOutput" @click="saveOutput">保存并重新生成 Word</el-button></div></template><article v-else class="markdown-body" v-html="renderMarkdown(currentOutput.output_text)"/></template></main>
        </div>
      </el-tab-pane>
    </el-tabs>
  </component>
</template>

<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { ElDrawer, ElMessage, ElMessageBox } from 'element-plus'
import { listBooks, listWritingProfiles, getWritingProfile, createWritingProfile, refineWritingProfile, deleteWritingProfile, imitateWriting, createLiteratureReview, cleanAiToneText, cleanAiToneDocx, listWritingOutputs, getWritingOutput, updateWritingOutput, reviewWritingOutput, writingOutputDownloadUrl, subscribeTask, listKnowledgeRecords, studyReports } from '../api'
import { notifyTaskSubmitted } from '../stores/taskCenter'
import { renderMarkdown } from '../utils/markdown'
import StudyEmptyState from './StudyEmptyState.vue'

const props=defineProps({ modelValue:Boolean, embedded:{type:Boolean,default:false} })
const emit=defineEmits(['update:modelValue'])
const mode=ref('dna'),profiles=ref([]),profileDetail=ref(null),selectedProfileId=ref(null),selectedRevisionId=ref(null),compareRevisionId=ref(null),creating=ref(false),submitting=ref(false),generating=ref(false),reviewingLiterature=ref(false),cleaning=ref(false)
const bookOptions=ref([]),booksLoading=ref(false),refineBooks=ref([]),removeBookIds=ref([]),refineFeedback=ref(''),cleanProfileId=ref(null),cleanText=ref(''),currentOutput=ref(null)
const knowledgeOptions=ref([]),knowledgeLoading=ref(false)
const outputs=ref([]),outputTotal=ref(0),acceptedIndexes=ref([]),reviewing=ref(false),editingOutput=ref(false),savingOutput=ref(false),draftTitle=ref(''),draftText=ref('')
const genMode=ref('imitate'),genProfileId=ref(null),outputFilter=ref('')
const profileForm=ref({name:'',target_author:'',book_ids:[],rights_acknowledged:false})
const imitateForm=ref({topic:'',genre:'深度文章',length:1800,brief:'',knowledge_keys:[]})
const reviewForm=ref({title:'',question:'',book_ids:[],review_type:'narrative',discipline:'auto',length:3500,profile_id:null,ai_tone_constraints:true})
const readyProfiles=computed(()=>profiles.value.filter(p=>p.status==='ready'))
const generatedOutput=computed(()=>['imitation','literature_review'].includes(currentOutput.value?.kind)?currentOutput.value:null)
const activeRevision=computed(()=>profileDetail.value?.revisions?.find(item=>item.id===selectedRevisionId.value)||profileDetail.value?.revisions?.[0]||null)
const comparisonRevision=computed(()=>profileDetail.value?.revisions?.find(item=>item.id===compareRevisionId.value)||null)
const outputChanges=computed(()=>Array.isArray(currentOutput.value?.audit?.changes)?currentOutput.value.audit.changes:[])
const violationInfo=v=>{if(!v||typeof v!=='object')return null;const items=[['“不是……而是……”句式',v.not_but],['翻案式铺垫',v.fan_an],['定语后置嫌疑',v.postposed_attr],['例证复用',Array.isArray(v.repeated_example_pairs)?v.repeated_example_pairs.map(pair=>`${pair[0]} ≈ ${pair[1]}`):null]];const hits=items.filter(([,list])=>Array.isArray(list)&&list.length);if(!hits.length)return null;return{total:hits.reduce((sum,[,list])=>sum+list.length,0),detail:hits.map(([label,list])=>`${label} ${list.length} 处`).join('、'),samples:hits.flatMap(([,list])=>list).slice(0,4).join('；')}}
const currentViolations=computed(()=>violationInfo(currentOutput.value?.audit?.ai_tone_violations))
const currentRemaining=computed(()=>violationInfo(currentOutput.value?.audit?.remaining_violations))
const freshnessWarning=computed(()=>['stale','missing','unknown'].includes(currentOutput.value?.source_freshness?.status))
const freshnessType=computed(()=>currentOutput.value?.source_freshness?.status==='unknown'?'info':'warning')
const canDistill=computed(()=>profileForm.value.name.trim()&&profileForm.value.book_ids.length>=20&&profileForm.value.rights_acknowledged)
const canGenerateReview=computed(()=>reviewForm.value.title.trim().length>=2&&reviewForm.value.question.trim().length>=4&&reviewForm.value.book_ids.length>=2)
const statusText=s=>({pending:'排队中',running:'蒸馏中',ready:'可使用',failed:'需重试'}[s]||s)
const statusType=s=>({ready:'success',failed:'danger',running:'warning',pending:'info'}[s]||'info')
const outputKindText=kind=>({imitation:'独立新作',literature_review:'多文献综述',ai_tone:'白名单去 AI 味'}[kind]||kind)
const searchBooks=async(q='')=>{booksLoading.value=true;try{const r=await listBooks({status:'ready',q:q.trim()||undefined,page_size:40});const selected=bookOptions.value.filter(b=>profileForm.value.book_ids.includes(b.id)||refineBooks.value.includes(b.id)||reviewForm.value.book_ids.includes(b.id));bookOptions.value=[...new Map([...selected,...r.items].map(b=>[b.id,b])).values()]}finally{booksLoading.value=false}}
const loadProfiles=async()=>{profiles.value=(await listWritingProfiles()).items||[];if(!readyProfiles.value.some(item=>item.id===genProfileId.value))genProfileId.value=readyProfiles.value[0]?.id||null}
const loadGenProfile=async id=>{genProfileId.value=id||null;const target=readyProfiles.value.find(item=>item.id===genProfileId.value);let bookIds=[];if(target)bookIds=(await getWritingProfile(target.id)).book_ids||[];await loadKnowledgeOptions(bookIds)}
const loadKnowledgeOptions=async(bookIds=[])=>{knowledgeLoading.value=true;try{const [records,reports]=await Promise.all([listKnowledgeRecords({book_ids:bookIds,record_types:['note','evidence'],page_size:100}),studyReports(1,50)]);const objects=(records.items||[]).map(item=>({value:`${item.record_type}:${item.id}`,label:`${item.record_type==='note'?'笔记':'证据卡'}｜${item.title}`}));const reportObjects=(reports.items||[]).filter(item=>(item.book_ids||[]).every(id=>bookIds.includes(id))).map(item=>({value:`report:${item.id}`,label:`批判性审查｜${item.focus||'综合研读'}`}));knowledgeOptions.value=[...reportObjects,...objects];imitateForm.value.knowledge_keys=imitateForm.value.knowledge_keys.filter(key=>knowledgeOptions.value.some(item=>item.value===key))}finally{knowledgeLoading.value=false}}
const openProfile=async id=>{selectedProfileId.value=id;profileDetail.value=await getWritingProfile(id);selectedRevisionId.value=profileDetail.value.revisions?.[0]?.id||null;compareRevisionId.value=null;removeBookIds.value=[]}
const loadOutputs=async(page=1)=>{const result=await listWritingOutputs({page,page_size:20,exclude_official:true,kind:outputFilter.value||undefined});outputs.value=result.items||[];outputTotal.value=result.total||0}
const loadAll=async()=>{await Promise.all([loadProfiles(),searchBooks(''),loadOutputs()]);if(selectedProfileId.value)await openProfile(selectedProfileId.value);if(genProfileId.value)await loadGenProfile(genProfileId.value)}
const followTask=(taskId,profileId)=>{notifyTaskSubmitted();subscribeTask(taskId,()=>{},{signal:taskAbort.signal}).then(async()=>{await loadProfiles();await openProfile(profileId)}).catch(()=>loadProfiles())}
const createProfile=async()=>{submitting.value=true;try{const r=await createWritingProfile(profileForm.value);creating.value=false;await loadProfiles();await openProfile(r.profile_id);followTask(r.task_id,r.profile_id);ElMessage.success('蒸馏已进入全局任务中心')}catch(e){ElMessage.error(e.message)}finally{submitting.value=false}}
const toggleCorpusRemoval=id=>{removeBookIds.value=removeBookIds.value.includes(id)?removeBookIds.value.filter(value=>value!==id):[...removeBookIds.value,id]}
const removeProfile=async()=>{const p=profileDetail.value;if(!p)return;try{await ElMessageBox.confirm(`确定删除「${p.name}」？全部蒸馏版本（v1–v${p.current_version}）与语料清单会一并删除，且无法恢复；已生成的写作输出会保留，仅解除与该项目的关联。`,'删除 Writing DNA 项目',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'})}catch(e){return}
submitting.value=true;try{await deleteWritingProfile(p.id);if(selectedProfileId.value===p.id){selectedProfileId.value=null;profileDetail.value=null;knowledgeOptions.value=[]}await loadProfiles();ElMessage.success('项目已删除，写作输出仍保留')}catch(e){ElMessage.error(e.message)}finally{submitting.value=false}}
const refineProfile=async()=>{submitting.value=true;try{const r=await refineWritingProfile(selectedProfileId.value,{book_ids:refineBooks.value,remove_book_ids:removeBookIds.value,feedback:refineFeedback.value});refineBooks.value=[];removeBookIds.value=[];refineFeedback.value='';followTask(r.task_id,r.profile_id);if(r.pruned_book_ids?.length)ElMessage.info(`已自动移除 ${r.pruned_book_ids.length} 篇已删除的书目`);ElMessage.success('新版本已提交，旧版本会保留')}catch(e){ElMessage.error(e.message)}finally{submitting.value=false}}
const prepareOutput=row=>{currentOutput.value=row;editingOutput.value=false;draftTitle.value=row?.title||'';draftText.value=row?.output_text||'';const saved=row?.audit?.accepted_indexes;acceptedIndexes.value=Array.isArray(saved)?[...saved]:outputChanges.value.map((_,index)=>index)}
const runViaTask=async(submitted,{success,failure}={})=>{notifyTaskSubmitted();const task=await subscribeTask(submitted.task_id,()=>{},{signal:taskAbort.signal});if(task.status==='failed'||task.status==='cancelled')throw new Error(task.error||task.message||failure||'任务未完成');const row=await getWritingOutput(task.result?.output_id);prepareOutput(row);await loadOutputs();ElMessage.success(success||'任务已完成');return row}
const runImitation=async()=>{const payload={...imitateForm.value,knowledge_note_ids:[],evidence_card_ids:[],report_ids:[]};for(const key of payload.knowledge_keys){const [type,id]=key.split(':');if(type==='note')payload.knowledge_note_ids.push(Number(id));else if(type==='evidence')payload.evidence_card_ids.push(Number(id));else if(type==='report')payload.report_ids.push(Number(id))}delete payload.knowledge_keys;generating.value=true;try{await runViaTask(await imitateWriting(genProfileId.value,payload),{success:'已从选定知识对象生成独立新作与 Word',failure:'仿写任务未完成'})}catch(e){ElMessage.error(e.message)}finally{generating.value=false}}
const runLiteratureReview=async()=>{reviewForm.value.length=Math.max(1200,Math.min(20000,Number(reviewForm.value.length)||3500));reviewingLiterature.value=true;try{await runViaTask(await createLiteratureReview({...reviewForm.value,profile_id:reviewForm.value.profile_id||null}),{success:'多文献综述与证据审计已生成',failure:'综述任务未完成'})}catch(e){ElMessage.error(e.message)}finally{reviewingLiterature.value=false}}
const sendToTone=output=>{if(!output?.output_text)return;cleanText.value=output.output_text;cleanProfileId.value=output.profile_id||reviewForm.value.profile_id||genProfileId.value||null;mode.value='clean';ElMessage.info('已送入去 AI 味；处理后逐条决定是否采用')}
const sendReviewToTone=()=>sendToTone(currentOutput.value)
const openInOutputs=async id=>{await openOutput(id);mode.value='outputs'}
const runTextClean=async()=>{cleaning.value=true;try{await runViaTask(await cleanAiToneText({text:cleanText.value,title:'去 AI 味稿件',profile_id:cleanProfileId.value||null}),{success:'候选改写已生成，请逐条审阅',failure:'去 AI 味任务未完成'})}catch(e){ElMessage.error(e.message)}finally{cleaning.value=false}}
const runDocxClean=async file=>{cleaning.value=true;try{await runViaTask(await cleanAiToneDocx(file.raw,cleanProfileId.value),{success:'Word 候选改写已生成，请逐条审阅',failure:'Word 去 AI 味任务未完成'})}catch(e){ElMessage.error(e.message)}finally{cleaning.value=false}}
const toggleAllChanges=value=>{acceptedIndexes.value=value?outputChanges.value.map((_,index)=>index):[]}
const applyReviewedChanges=async()=>{reviewing.value=true;try{prepareOutput(await reviewWritingOutput(currentOutput.value.id,acceptedIndexes.value));await loadOutputs();ElMessage.success('已按人工选择重新生成 Word')}catch(e){ElMessage.error(e.message)}finally{reviewing.value=false}}
const beginEditOutput=()=>{draftTitle.value=currentOutput.value?.title||'';draftText.value=currentOutput.value?.output_text||'';editingOutput.value=true}
const cancelEditOutput=()=>{editingOutput.value=false}
const saveOutput=async()=>{if(!draftTitle.value.trim()||!draftText.value.trim())return ElMessage.warning('标题和正文不能为空');savingOutput.value=true;try{prepareOutput(await updateWritingOutput(currentOutput.value.id,{title:draftTitle.value,output_text:draftText.value}));await loadOutputs();ElMessage.success('稿件和 Word 已更新')}catch(e){ElMessage.error(e.message)}finally{savingOutput.value=false}}
const openOutput=async id=>{try{prepareOutput(await getWritingOutput(id))}catch(e){ElMessage.error(e.message)}}
const formatDate=value=>value?new Date(value).toLocaleDateString('zh-CN'):'—'
// 离开页面后必须停止任务跟踪，否则 SSE + 1.8s 轮询会一直占用连接。
const taskAbort = new AbortController()
onMounted(()=>{if(props.embedded)loadAll()})
onUnmounted(()=>{taskAbort.abort()})
</script>

